# Get the selected manufacturing orders from the environment context
selected_ids = env.context.get('active_ids', [])

if not selected_ids:
    raise UserError(_("Please select at least one manufacturing order."))

# Open the unified wizard that allows switching between assign/unassign modes
action = {
    'type': 'ir.actions.act_window',
    'name': 'Batch Material Management',
    'res_model': 'mrp.production.batch.assignment.wizard',
    'view_mode': 'form',
    'target': 'new',
    'context': {'active_ids': selected_ids, 'active_model': 'mrp.production'}
}
